-- verify after 62-64 (SELECT only): per draft - R&W difficulty by module/route, domain counts, readiness, problems shared with other live sets
-- generated by scripts/prod-open/sat-rw-hard-sql.ts. Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.

select s.name, s.version_no, s.status, s.readiness_status,
  (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id and i.section = 'rw') as rw_items,
  (select count(*) filter (where i.difficulty = 'hard') from mock_exam_set_items i where i.exam_set_id = s.id and i.section = 'rw' and i.module_key = 'rw_m1') as m1_hard,
  (select count(*) filter (where i.difficulty = 'hard') from mock_exam_set_items i where i.exam_set_id = s.id and i.section = 'rw' and i.module_key = 'rw_m2' and i.route = 'lower') as m2_lower_hard,
  (select count(*) filter (where i.difficulty = 'hard') from mock_exam_set_items i where i.exam_set_id = s.id and i.section = 'rw' and i.module_key = 'rw_m2' and i.route = 'higher') as m2_higher_hard,
  (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id and exists (select 1 from mock_exam_set_items o join mock_exam_sets os on os.id = o.exam_set_id and os.archived_at is null and os.status <> 'archived' and os.id <> s.id and os.set_group_id <> s.set_group_id where o.problem_id = i.problem_id)) as problems_shared_with_other_exams
from mock_exam_sets s where s.status = 'draft' and s.archived_at is null and s.readiness_report->>'rwHard1022' = 'true' order by length(s.name), s.name;
